from pathlib import Path
root=Path(__file__).resolve().parent.parent
s=(root/'source/playground-template.html').read_text()
s=s.replace('Fase A','Fases A + B').replace('transformação principal','transformação e estados principais').replace('DARK NEBULA / 01','DARK NEBULA / 02')
s=s.replace('Reproduzir ciclo completo</button>','Ciclo de transformação (Fase A)</button><button id="full-flow">Reproduzir fluxo completo (A + B)</button>')
s=s.replace('<div class="line"></div><div><h2>Inspeção visual', '''<div class="line"></div><div><h2>Estados ativos</h2><div class="state-grid"><button data-state="listening" aria-pressed="false">Listening</button><button data-state="thinking" aria-pressed="false">Thinking</button><button data-state="executing" aria-pressed="false">Executing</button><button data-state="speaking" aria-pressed="false">Speaking</button></div></div><div class="line"></div><div><h2>Reatividade de áudio</h2><label for="audio-source">Fonte da amplitude</label><select id="audio-source"><option value="manual">Manual</option><option value="auto">Simulação automática</option><option value="mic">Microfone (opcional)</option></select><label for="audio">Amplitude manual · <span id="audio-value">0%</span></label><input id="audio" type="range" min="0" max="100" value="0"><div class="audio-row"><small>Amplitude efetiva</small><span class="readout" id="audio-live">0%</span></div><div class="timeline meter"><div id="audio-meter"></div></div><small id="mic-status" role="status"></small><button id="mic-stop" disabled>Desligar microfone</button></div><div class="line"></div><div><h2>Inspeção visual''')
s=s.replace('Áudio e demais estados serão adicionados nas próximas fases.','Áudio reativo em Listening e Speaking. Nenhum áudio é armazenado ou enviado. Microfone exige permissão e contexto compatível.')
s=s.replace('</style>','''\n.state-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.state-grid button[aria-pressed=true]{background:var(--cosmic);border-color:var(--nova)}.audio-row{display:flex;justify-content:space-between;align-items:center}.meter{height:5px;margin:5px 0 8px}#mic-status{display:block;margin-bottom:8px}#mic-stop{width:100%;font-size:12px}button:disabled{opacity:.4;cursor:default}.layout{align-items:start}.stage{height:500px}.side{gap:15px}#audio-source{margin-bottom:10px}@media(min-width:761px){.layout>section{position:sticky;top:16px}}@media(max-width:760px){.stage{height:360px}}\n</style>''')
s=s.split('<script>/* GEOMETRY_SOURCE */</script>')[0]+'<script>\n'+(root/'source/geometry.js').read_text()+'\n'+(root/'source/motion.js').read_text()+'\n</script><script>\n'+(root/'source/lab-phase-b.js').read_text()+'\n</script></body></html>'
(root/'previews/playground-phase-b.html').write_text(s)
